input.proposed_solution:
Rename fmtDate to formatIsoDate in src/dates.js and update its three callers (src/reports.js, src/invoices.js, src/audit/log.js) and the test. No behaviour change.

Patch (already applied in the repository snapshot):
```diff
--- a/src/audit/log.js
+++ b/src/audit/log.js
@@ -1,7 +1,7 @@
 // @ts-check
-import { fmtDate } from "../dates.js";
+import { formatIsoDate } from "../dates.js";

 /** @param {{ user: string, action: string, at: Date }} e */
 export function auditLine(e) {
-  return `${fmtDate(e.at)} ${e.user} ${e.action}`;
+  return `${formatIsoDate(e.at)} ${e.user} ${e.action}`;
 }
--- a/src/dates.js
+++ b/src/dates.js
@@ -4,6 +4,6 @@
  * @param {Date} d
  * @returns {string} YYYY-MM-DD (UTC)
  */
-export function fmtDate(d) {
+export function formatIsoDate(d) {
   return d.toISOString().slice(0, 10);
 }
--- a/src/invoices.js
+++ b/src/invoices.js
@@ -1,7 +1,7 @@
 // @ts-check
-import { fmtDate } from "./dates.js";
+import { formatIsoDate } from "./dates.js";

 /** @param {{ number: string, issued: Date, due: Date }} i */
 export function invoiceDates(i) {
-  return { issued: fmtDate(i.issued), due: fmtDate(i.due) };
+  return { issued: formatIsoDate(i.issued), due: formatIsoDate(i.due) };
 }
--- a/src/reports.js
+++ b/src/reports.js
@@ -1,7 +1,7 @@
 // @ts-check
-import { fmtDate } from "./dates.js";
+import { formatIsoDate } from "./dates.js";

 /** @param {{ title: string, at: Date }} r */
 export function reportHeader(r) {
-  return `${r.title} — ${fmtDate(r.at)}`;
+  return `${r.title} — ${formatIsoDate(r.at)}`;
 }
--- a/test/dates.test.js
+++ b/test/dates.test.js
@@ -1,9 +1,9 @@
 import { test } from "node:test";
 import assert from "node:assert/strict";
-import { fmtDate } from "../src/dates.js";
+import { formatIsoDate } from "../src/dates.js";
 import { invoiceDates } from "../src/invoices.js";

-test("formats as UTC date", () => assert.equal(fmtDate(new Date("2026-03-05T23:30:00Z")), "2026-03-05"));
+test("formats as UTC date", () => assert.equal(formatIsoDate(new Date("2026-03-05T23:30:00Z")), "2026-03-05"));
 test("invoice dates", () => {
   assert.deepEqual(invoiceDates({ number: "1", issued: new Date("2026-01-01T00:00:00Z"), due: new Date("2026-01-31T00:00:00Z") }), { issued: "2026-01-01", due: "2026-01-31" });
 });
```
